css:
:root {
    --bg: #07111e;
    --panel: #0d1b30;
    --panel2: #12243f;
    --line: #1f3558;
    --text: #e6edf8;
    --text-dim: #c7d6ec;
    --text-faint: #9cb0cf;
    --accent: #7c9eff;
    --accent2: #5fd4c4;
    --warn: #f2b866;
    --sidebar-w: 300px;
}
* {
    box-sizing: border-box;
}
html,
body {
    margin: 0;
    overflow-x: hidden;
}
body {
    background: var(--bg);
    color: var(--text);
    font-family:
        'Noto Sans JP', 'Hiragino Kaku Gothic ProN', 'Yu Gothic', Meiryo, sans-serif;
    font-size: 16px;
    line-height: 1.85;
    -webkit-font-smoothing: antialiased;
}
html {
    scroll-behavior: smooth;
}
.layout {
    display: block;
}
.sidebar {
    position: fixed;
    left: 0;
    top: 0;
    bottom: 0;
    width: var(--sidebar-w);
    background: var(--panel);
    border-right: 1px solid var(--line);
    overflow-y: auto;
    padding: 22px 14px 40px;
    z-index: 20;
}
.sidebar .brand {
    font-size: 12px;
    letter-spacing: 0.08em;
    color: var(--accent);
    font-weight: 700;
    text-transform: uppercase;
    margin: 0 8px 14px;
}
.sidebar ul {
    list-style: none;
    margin: 0;
    padding: 0;
}
.sidebar a {
    display: block;
    color: var(--text-dim);
    text-decoration: none;
    font-size: 13.5px;
    line-height: 1.5;
    padding: 6px 10px;
    border-radius: 6px;
    border-left: 2px solid transparent;
}
.sidebar a:hover {
    background: var(--panel2);
    color: #fff;
}
.sidebar a.active {
    color: #fff;
    background: rgba(124, 158, 255, 0.14);
    border-left-color: var(--accent);
}
.nav-h2 > a {
    font-weight: 700;
    color: var(--text);
}
.nav-sub {
    margin: 2px 0 8px 12px !important;
}
.nav-sub a {
    font-size: 12.5px;
    color: var(--text-faint);
}
.nav-toggle {
    display: none;
    position: fixed;
    top: 12px;
    left: 12px;
    z-index: 30;
    background: var(--panel2);
    color: var(--text);
    border: 1px solid var(--line);
    border-radius: 8px;
    padding: 8px 12px;
    font: inherit;
    font-size: 14px;
    cursor: pointer;
}
.main {
    margin-left: var(--sidebar-w);
    padding: 0 48px 80px;
}
.hero {
    position: relative;
    padding: 56px 0 34px;
    border-bottom: 1px solid var(--line);
    margin-bottom: 28px;
    overflow: hidden;
}
.hero::before {
    content: '';
    position: absolute;
    right: -120px;
    top: -160px;
    width: 520px;
    height: 520px;
    background: radial-gradient(circle, rgba(124, 158, 255, 0.22), transparent 65%);
    pointer-events: none;
}
.eyebrow {
    display: inline-block;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.08em;
    color: var(--accent);
    border: 1px solid rgba(124, 158, 255, 0.45);
    background: rgba(124, 158, 255, 0.1);
    padding: 4px 14px;
    border-radius: 999px;
}
.hero-title {
    font-size: 28px;
    font-weight: 800;
    color: #fff;
    line-height: 1.4;
    margin: 16px 0 8px;
    position: relative;
}
.hero-sub {
    color: var(--text-dim);
    font-size: 15px;
    margin: 0 0 18px;
    position: relative;
}
.hero-meta {
    display: flex;
    flex-wrap: wrap;
    position: relative;
    border-top: 1px solid var(--line);
    padding-top: 14px;
}
.hero-meta .m {
    padding: 2px 22px 2px 0;
    margin-right: 22px;
    border-right: 1px solid var(--line);
}
.hero-meta .m:last-child {
    border-right: 0;
}
.hero-meta .l {
    display: block;
    font-size: 11px;
    letter-spacing: 0.06em;
    color: var(--text-faint);
    text-transform: uppercase;
}
.hero-meta .v {
    font-size: 14.5px;
    color: var(--text);
}
.hero-note {
    margin-top: 14px;
    color: var(--text-faint);
    font-size: 13.5px;
    position: relative;
}
.hero-note p {
    margin: 2px 0;
}
h2 {
    font-size: 24px;
    font-weight: 800;
    color: #fff;
    margin: 56px 0 18px;
    padding-bottom: 10px;
    border-bottom: 1px solid var(--line);
    scroll-margin-top: 20px;
}
h3 {
    font-size: 19px;
    font-weight: 700;
    color: #dbe6ff;
    margin: 34px 0 12px;
    scroll-margin-top: 20px;
}
h4 {
    font-size: 16.5px;
    font-weight: 700;
    color: var(--accent2);
    margin: 26px 0 8px;
    scroll-margin-top: 20px;
}
p,
li {
    color: var(--text-dim);
}
strong {
    color: #fff;
    font-weight: 700;
}
a {
    color: var(--accent);
    overflow-wrap: anywhere;
}
ul,
ol {
    padding-left: 1.4em;
}
li {
    margin: 4px 0;
}
code:not(pre code) {
    font-family: 'JetBrains Mono', ui-monospace, Menlo, Consolas, monospace;
    font-size: 0.9em;
    background: var(--panel2);
    color: #cfe0ff;
    padding: 1px 6px;
    border-radius: 5px;
    overflow-wrap: anywhere;
    word-break: break-word;
}
.table-scroll {
    overflow-x: auto;
    margin: 16px 0 22px;
    border: 1px solid var(--line);
    border-radius: 10px;
    background: var(--panel);
}
table {
    border-collapse: collapse;
    width: 100%;
    font-size: 14.5px;
}
th,
td {
    padding: 10px 14px;
    border-bottom: 1px solid var(--line);
    text-align: left;
    vertical-align: top;
    color: var(--text-dim);
}
th {
    background: var(--panel2);
    color: #fff;
    font-weight: 700;
    white-space: nowrap;
}
tr:last-child td {
    border-bottom: 0;
}
td {
    min-width: 80px;
}
.callout {
    margin: 18px 0;
    padding: 14px 18px;
    background: rgba(124, 158, 255, 0.08);
    border: 1px solid rgba(124, 158, 255, 0.3);
    border-left: 4px solid var(--accent);
    border-radius: 10px;
}
.callout p {
    margin: 6px 0;
}
.callout-warn {
    background: rgba(242, 184, 102, 0.08);
    border-color: rgba(242, 184, 102, 0.35);
    border-left-color: var(--warn);
}
.mermaid-diagram {
    display: block;
    overflow-x: auto;
    margin: 20px 0 26px;
    padding: 20px;
    background: var(--panel);
    border: 1px solid var(--line);
    border-radius: 12px;
}
.mermaid-diagram svg {
    display: block;
    margin-left: auto;
    margin-right: auto;
    max-width: none;
}
.mermaid-diagram p {
    color: inherit;
    margin: 0;
}
.mermaid-diagram foreignObject {
    overflow: visible;
}
.mermaid-diagram foreignObject div,
.mermaid-diagram foreignObject span,
.mermaid-diagram foreignObject p {
    white-space: normal !important;
}
details {
    margin: 16px 0;
    background: var(--panel);
    border: 1px solid var(--line);
    border-radius: 10px;
    padding: 4px 18px;
}
summary {
    cursor: pointer;
    color: #fff;
    font-weight: 700;
    padding: 10px 0;
}
.checklist-card,
.quiz-wrap {
    margin: 20px 0 28px;
    background: var(--panel);
    border: 1px solid var(--line);
    border-radius: 14px;
    padding: 18px 20px;
}
.cl-head,
.quiz-head {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 12px 16px;
    margin-bottom: 16px;
}
.cl-title,
.quiz-title {
    font-weight: 800;
    color: #fff;
    font-size: 15px;
}
.cl-bar {
    flex: 1;
    min-width: 140px;
    height: 10px;
    background: var(--panel2);
    border-radius: 999px;
    overflow: hidden;
}
.cl-fill,
.q-fill {
    height: 100%;
    width: 0;
    background: linear-gradient(90deg, var(--accent), var(--accent2));
    transition: width 0.25s;
}
.cl-count,
.q-count {
    font-size: 13.5px;
    color: var(--text-dim);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
}
.cl-reset,
.qbtn {
    font: inherit;
    font-size: 12.5px;
    color: var(--text-dim);
    background: var(--panel2);
    border: 1px solid var(--line);
    border-radius: 8px;
    padding: 5px 12px;
    cursor: pointer;
}
.cl-reset:hover,
.qbtn:hover {
    border-color: var(--accent);
    color: #fff;
}
.quiz-btns {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}
.cl-grid,
.quiz-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
}
.cl-item {
    position: relative;
    display: flex;
    gap: 12px;
    align-items: flex-start;
    padding: 14px 16px;
    background: var(--panel2);
    border: 1px solid var(--line);
    border-radius: 12px;
    cursor: pointer;
    transition:
        border-color 0.15s,
        background 0.15s;
}
.cl-item:hover {
    border-color: var(--accent);
}
.cl-item:focus-within {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
}
.cl-item input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
}
.cl-num {
    flex: none;
    width: 30px;
    height: 30px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    font-weight: 800;
    font-size: 13px;
    color: var(--accent);
    background: rgba(124, 158, 255, 0.14);
    border: 1px solid rgba(124, 158, 255, 0.4);
}
.cl-item input:checked ~ .cl-num {
    font-size: 0;
    background: var(--accent2);
    border-color: var(--accent2);
}
.cl-item input:checked ~ .cl-num::after {
    content: '\2713';
    font-size: 16px;
    color: #06231f;
}
.cl-item:has(input:checked) {
    border-color: rgba(95, 212, 196, 0.55);
    background: rgba(95, 212, 196, 0.07);
}
.cl-text {
    color: var(--text-dim);
    line-height: 1.7;
    min-width: 0;
    overflow-wrap: anywhere;
}
.cl-item input:checked ~ .cl-text {
    color: var(--text-faint);
}
.cl-done {
    display: none;
    margin-top: 14px;
    padding: 10px 14px;
    border-radius: 10px;
    background: rgba(95, 212, 196, 0.1);
    border: 1px solid rgba(95, 212, 196, 0.4);
    color: #bff3ea;
    font-size: 14px;
}
.checklist-card.complete .cl-done {
    display: block;
}
.q-card {
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 14px 16px;
    background: var(--panel2);
    border: 1px solid var(--line);
    border-radius: 12px;
    min-width: 0;
}
.q-card.known {
    border-color: rgba(95, 212, 196, 0.55);
    background: rgba(95, 212, 196, 0.06);
}
.q-top {
    display: flex;
    gap: 12px;
    align-items: flex-start;
}
.q-badge {
    flex: none;
    min-width: 38px;
    text-align: center;
    padding: 3px 8px;
    border-radius: 8px;
    font-weight: 800;
    font-size: 13px;
    color: #06231f;
    background: var(--accent);
    letter-spacing: 0.02em;
}
.q-card.known .q-badge {
    background: var(--accent2);
}
.q-text {
    color: #e9f0ff;
    line-height: 1.7;
    min-width: 0;
    overflow-wrap: anywhere;
}
.q-ans {
    margin: 0;
    padding: 0;
    background: transparent;
    border: 1px dashed var(--line);
    border-radius: 10px;
}
.q-ans summary {
    cursor: pointer;
    font-size: 13.5px;
    font-weight: 700;
    color: var(--accent);
    padding: 8px 14px;
    list-style: none;
}
.q-ans summary::-webkit-details-marker {
    display: none;
}
.q-ans summary::before {
    content: '\25B6';
    display: inline-block;
    margin-right: 8px;
    font-size: 10px;
    transition: transform 0.15s;
}
.q-ans[open] summary::before {
    transform: rotate(90deg);
}
.q-ans[open] {
    border-style: solid;
    border-color: rgba(124, 158, 255, 0.4);
    background: rgba(124, 158, 255, 0.06);
}
.q-body {
    padding: 2px 14px 12px;
    color: var(--text-dim);
    font-size: 14.5px;
    line-height: 1.75;
    overflow-wrap: anywhere;
}
.q-know {
    margin-top: auto;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    align-self: flex-start;
    font-size: 13px;
    color: var(--text-faint);
    cursor: pointer;
}
.q-know input {
    accent-color: var(--accent2);
    width: 16px;
    height: 16px;
}
@media (max-width: 1180px) {
    .cl-grid,
    .quiz-grid {
        grid-template-columns: minmax(0, 1fr);
    }
}
.page-foot {
    margin-top: 56px;
    color: var(--text-faint);
    font-size: 13px;
}
@media (max-width: 900px) {
    .nav-toggle {
        display: block;
    }
    .sidebar {
        transform: translateX(-100%);
        transition: transform 0.2s;
    }
    .sidebar.open {
        transform: none;
        box-shadow: 0 0 40px rgba(0, 0, 0, 0.6);
    }
    .main {
        margin-left: 0;
        padding: 0 18px 60px;
    }
    .hero {
        padding-top: 64px;
    }
    .hero-title {
        font-size: 23px;
    }
    .hero-meta .m {
        border-right: 0;
        border-bottom: 1px solid var(--line);
        width: 100%;
        margin: 0;
        padding: 8px 0;
    }
    .hero-meta .m:last-child {
        border-bottom: 0;
    }
    h2 {
        font-size: 21px;
    }
}
